        // 合并团队，队长为两个团队队长中序号较小的那个
        int rootA = find(a);
        int rootB = find(b);
        int newRoot = Math.min(rootA, rootB);
        ans[rootA] = newRoot;
        ans[rootB] = newRoot;
    }
