package main
​
import (
    "fmt"
)
​
type Team struct {
    parent []int
}
​
// 初始化 UnionFind 结构
func NewTeam(n int) *Team {
    uf := &Team{
        parent: make([]int, n+1),
    }
    for i := 0; i <= n; i++ {
        uf.parent[i] = i
    }
    return uf
}
​
// 找团队队长（路径压缩优化）
func (uf *Team) Find(a int) int {
    if uf.parent[a] != a {
        uf.parent[a] = uf.Find(uf.parent[a])
    }
    return uf.parent[a]
}
​
// 合并团队
func (uf *Team) Merge(a, b int) {
    rootA := uf.Find(a)
    rootB := uf.Find(b)
    newRoot := min(rootA, rootB)
    uf.parent[rootA] = newRoot
    uf.parent[rootB] = newRoot
}
​
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
​
func main() {
    var n, m int
    fmt.Scan(&n, &m)
​
    // n, m 值大小合法性判断
    if n < 1 || m < 1 || n >= 100000 || m >= 100000 {
        fmt.Println("Null")
        return
    }
​
    // 初始化 Team
    uf := NewTeam(n)
​
    for i := 0; i < m; i++ {
        var a, b, c int
        fmt.Scan(&a, &b, &c)
​
        // 输入值合法性判断
        if a > n || b > n || a < 1 || b < 1 {
            fmt.Println("da pian zi")
            continue
        }
​
        if c == 0 {
            // 合并团队
            uf.Merge(a, b)
        } else if c == 1 {
            // 判断是否在同一团队
            if uf.Find(a) == uf.Find(b) {
                fmt.Println("we are a team")
            } else {
                fmt.Println("we are not a team")
            }
        } else {
            fmt.Println("da pian zi")
        }
    }
}
